from __future__ import annotations

import json
from pathlib import Path
from typing import Any

SCHEMA_DIRNAME = "schema"
SCHEMA_FILENAME = "problem.schema.json"
SCHEMA_DIRECTIVE = f"#:schema ./{SCHEMA_DIRNAME}/{SCHEMA_FILENAME}"

_DO_NOT_EDIT = (
    "Generated by `gantry schema` from the gemseo-gantry problem model. "
    "Do not edit by hand; regenerate with `gantry schema`."
)


def build_schema() -> dict[str, Any]:
    """Return the JSON Schema for a problem-definition TOML.

    Pure passthrough of the canonical model's `model_json_schema()`, plus a
    single top-level `$comment` marking the file as generated. No other
    transform is applied (identifier-shape and semantic checks live in the
    validation pipeline / `gantry validate --watch`, not the schema).
    """
    from .parser.toml_data_model import TomlProblemDefinition

    schema = TomlProblemDefinition.model_json_schema()
    schema["$comment"] = _DO_NOT_EDIT
    return schema


def schema_json() -> str:
    """Serialize `build_schema()` deterministically (2-space indent, trailing newline)."""
    return json.dumps(build_schema(), indent=2) + "\n"


def write_schema(project_dir: Path) -> Path:
    """Write `project_dir/schema/problem.schema.json` and return its path."""
    target = project_dir / SCHEMA_DIRNAME / SCHEMA_FILENAME
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(schema_json(), encoding="utf-8")
    return target
